units.name:
SettingsView/current.config.redaction_rules
    .map((rule, index) => {
      try {
        new RegExp(rule.regex);
        return null;
      } catch {
        return index;
      }
    })
    .filter()#0

EvidenceService.evidence/actionable
      .map((e) => {
        if (e.kind === "screenshot") {
          const shot = e.payload as ScreenshotPayload | null;
          // Fail closed: a screenshot the agent suppressed (secure input
          // context, §1) must never become a viewable URL, even if a blob_id
          // somehow accompanies it. The contract says suppressed frames carry
          // no blob; a read path must not depend on the writer honoring that.
          return shot?.suppressed === true ? undefined : shot?.blob_id;
        }
        if (e.kind === "dom_snapshot") return (e.payload as DomPayload | null)?.blob_id;
        return undefined;
      })
      .filter()#0

generateCorpus(opts)
  .then((summary) => {
    console.log(
      `gen:events seed=${summary.seed} users=${summary.users} days=${summary.days} → ` +
        `${summary.events} desktop events in ${summary.batches} batches, ${summary.keyframes} keyframes, ` +
        `${summary.instances} planted instances (${summary.abandoned} abandoned)` +
        (summary.extension_events > 0
          ? `, ${summary.extension_events} extension events / ${summary.dedup_pairs} dedup pairs`
          : "") +
        ` → ${out}`,
    );
  })
  .catch()#0
